content:
9800                  xmlFree(buf);
  9801                  return;
  9802              }
  9803              count = 0;
  9804          }
  9805          NEXTL(l);
  9806          cur = CUR_CHAR(l);
  9807      }
  9808      buf[len] = 0;
  9809      ctxt->instate = XML_PARSER_CONTENT;
  9810      if (cur != '>') {
  9811          xmlFatalErrMsgStr(ctxt, XML_ERR_CDATA_NOT_FINISHED,
  9812                               "CData section not finished\n%.50s\n", buf);
  9813          xmlFree(buf);
  9814          return;
  9815      }
  9816      NEXTL(l);
  9817
  9818      /*
  9819       * OK the buffer is to be consumed as cdata.
  9820       */
  9821      if ((ctxt->sax != NULL) && (!ctxt->disableSAX)) {
  9822          if (ctxt->sax->cdataBlock != NULL)
  9823              ctxt->sax->cdataBlock(ctxt->userData, buf, len);
  9824          else if (ctxt->sax->characters != NULL)
  9825              ctxt->sax->characters(ctxt->userData, buf, len);
  9826      }
  9827      xmlFree(buf);
  9828  }
