  9830  /**
  9831   * xmlParseContentInternal:
  9832   * @ctxt:  an XML parser context
  9833   *
  9834   * Parse a content sequence. Stops at EOF or '</'. Leaves checking of
  9835   * unexpected EOF to the caller.
  9836   */
  9837
  9838  static void
  9839  xmlParseContentInternal(xmlParserCtxtPtr ctxt) {
  9840      int nameNr = ctxt->nameNr;
  9841
  9842      GROW;
  9843      while ((RAW != 0) &&
  9844             (ctxt->instate != XML_PARSER_EOF)) {
  9845          const xmlChar *test = CUR_PTR;
  9846          unsigned int cons = ctxt->input->consumed;
  9847          const xmlChar *cur = ctxt->input->cur;
  9848
  9849          /*
  9850           * First case : a Processing Instruction.
  9851           */
  9852          if ((*cur == '<') && (cur[1] == '?')) {
  9853              xmlParsePI(ctxt);
  9854          }
  9855
  9856          /*
  9857           * Second case : a CDSection
  9858           */
  9859          /* 2.6.0 test was *cur not RAW */
  9860          else if (CMP9(CUR_PTR, '<', '!', '[', 'C', 'D', 'A', 'T', 'A', '[')) {
  9861              xmlParseCDSect(ctxt);
  9862          }
  9863
  9864          /*
  9865           * Third case :  a comment
  9866           */
  9867          else if ((*cur == '<') && (NXT(1) == '!') &&
  9868                   (NXT(2) == '-') && (NXT(3) == '-')) {
  9869              xmlParseComment(ctxt);
  9870              ctxt->instate = XML_PARSER_CONTENT;
  9871          }
  9872
  9873          /*
  9874           * Fourth case :  a sub-element.
  9875           */
  9876          else if (*cur == '<') {
  9877              if (NXT(1) == '/') {
  9878                  if (ctxt->nameNr <= nameNr)
  9879                      break;
  9880                  xmlParseElementEnd(ctxt);
  9881              } else {
  9882                  xmlParseElementStart(ctxt);
  9883              }
  9884          }
  9885
  9886          /*
  9887           * Fifth case : a reference. If if has not been resolved,
  9888           *    parsing returns it's Name, create the node
  9889           */
  9890
  9891          else if (*cur == '&') {
  9892              xmlParseReference(ctxt);
  9893          }
  9894
  9895          /*
  9896           * Last case, text. Note that References are handled directly.
  9897           */
  9898          else {
  9899              xmlParseCharData(ctxt, 0);
  9900          }
  9901
  9902          GROW;
  9903          SHRINK;
  9904
  9905          if ((cons == ctxt->input->consumed) && (test == CUR_PTR)) {
  9906              xmlFatalErr(ctxt, XML_ERR_INTERNAL_ERROR,
  9907                          "detected an error in element content\n");
  9908              xmlHaltParser(ctxt);
  9909              break;
  9910          }
  9911      }
  9912  }
