  9914  /**
  9915   * xmlParseContent:
  9916   * @ctxt:  an XML parser context
  9917   *
  9918   * Parse a content sequence. Stops at EOF or '</'.
  9919   *
  9920   * [43] content ::= (element | CharData | Reference | CDSect | PI | Comment)*
  9921   */
  9922
  9923  void
  9924  xmlParseContent(xmlParserCtxtPtr ctxt) {
  9925      int nameNr = ctxt->nameNr;
  9926
  9927      xmlParseContentInternal(ctxt);
  9928
  9929      if ((ctxt->instate != XML_PARSER_EOF) && (ctxt->nameNr > nameNr)) {
  9930          const xmlChar *name = ctxt->nameTab[ctxt->nameNr - 1];
  9931          int line = ctxt->pushTab[ctxt->nameNr - 1].line;
  9932          xmlFatalErrMsgStrIntStr(ctxt, XML_ERR_TAG_NOT_FINISHED,
  9933                  "Premature end of data in tag %s line %d\n",
  9934                  name, line, NULL);
  9935      }
  9936  }
