  9938  /**
  9939   * xmlParseElement:
  9940   * @ctxt:  an XML parser context
  9941   *
  9942   * parse an XML element
  9943   *
  9944   * [39] element ::= EmptyElemTag | STag content ETag
  9945   *
  9946   * [ WFC: Element Type Match ]
  9947   * The Name in an element's end-tag must match the element type in the
  9948   * start-tag.
  9949   *
  9950   */
  9951
  9952  void
  9953  xmlParseElement(xmlParserCtxtPtr ctxt) {
  9954      if (xmlParseElementStart(ctxt) != 0)
  9955          return;
  9956
  9957      xmlParseContentInternal(ctxt);
  9958      if (ctxt->instate == XML_PARSER_EOF)
  9959          return;
  9960
  9961      if (CUR == 0) {
  9962          const xmlChar *name = ctxt->nameTab[ctxt->nameNr - 1];
  9963          int line = ctxt->pushTab[ctxt->nameNr - 1].line;
  9964          xmlFatalErrMsgStrIntStr(ctxt, XML_ERR_TAG_NOT_FINISHED,
  9965                  "Premature end of data in tag %s line %d\n",
  9966                  name, line, NULL);
  9967          return;
  9968      }
  9969
  9970      xmlParseElementEnd(ctxt);
  9971  }
