  9973  /**
  9974   * xmlParseElementStart:
  9975   * @ctxt:  an XML parser context
  9976   *
  9977   * Parse the start of an XML element. Returns -1 in case of error, 0 if an
  9978   * opening tag was parsed, 1 if an empty element was parsed.
  9979   */
  9980  static int
  9981  xmlParseElementStart(xmlParserCtxtPtr ctxt) {
  9982      const xmlChar *name;
  9983      const xmlChar *prefix = NULL;
  9984      const xmlChar *URI = NULL;
  9985      xmlParserNodeInfo node_info;
  9986      int line, tlen = 0;
  9987      xmlNodePtr ret;
  9988      int nsNr = ctxt->nsNr;
  9989
  9990      if (((unsigned int) ctxt->nameNr > xmlParserMaxDepth) &&
  9991          ((ctxt->options & XML_PARSE_HUGE) == 0)) {
  9992          xmlFatalErrMsgInt(ctxt, XML_ERR_INTERNAL_ERROR,
  9993                   "Excessive depth in document: %d use XML_PARSE_HUGE option\n",
  9994                            xmlParserMaxDepth);
  9995          xmlHaltParser(ctxt);
  9996          return(-1);
  9997      }
  9998
  9999      /* Capture start position */
 10000      if (ctxt->record_info) {
 10001          node_info.begin_pos = ctxt->input->consumed +
 10002                            (CUR_PTR - ctxt->input->base);
 10003          node_info.begin_line = ctxt->input->line;
 10004      }
 10005
 10006      if (ctxt->spaceNr == 0)
 10007          spacePush(ctxt, -1);
 10008      else if (*ctxt->space == -2)
 10009          spacePush(ctxt, -1);
 10010      else
 10011          spacePush(ctxt, *ctxt->space);
 10012
 10013      line = ctxt->input->line;
 10014  #ifdef LIBXML_SAX1_ENABLED
 10015      if (ctxt->sax2)
 10016  #endif /* LIBXML_SAX1_ENABLED */
 10017          name = xmlParseStartTag2(ctxt, &prefix, &URI, &tlen);
 10018  #ifdef LIBXML_SAX1_ENABLED
 10019      else
 10020          name = xmlParseStartTag(ctxt);
 10021  #endif /* LIBXML_SAX1_ENABLED */
 10022      if (ctxt->instate == XML_PARSER_EOF)
 10023          return(-1);
 10024      if (name == NULL) {
 10025          spacePop(ctxt);
 10026          return(-1);
 10027      }
 10028      if (ctxt->sax2)
 10029          nameNsPush(ctxt, name, prefix, URI, line, ctxt->nsNr - nsNr);
 10030  #ifdef LIBXML_SAX1_ENABLED
 10031      else
 10032          namePush(ctxt, name);
 10033  #endif /* LIBXML_SAX1_ENABLED */
 10034      ret = ctxt->node;
 10035
 10036  #ifdef LIBXML_VALID_ENABLED
 10037      /*
 10038       * [ VC: Root Element Type ]
 10039       * The Name in the document type declaration must match the element
 10040       * type of the root element.
 10041       */
 10042      if (ctxt->validate && ctxt->wellFormed && ctxt->myDoc &&
 10043          ctxt->node && (ctxt->node == ctxt->myDoc->children))
 10044          ctxt->valid &= xmlValidateRoot(&ctxt->vctxt, ctxt->myDoc);
 10045  #endif /* LIBXML_VALID_ENABLED */
 10046
 10047      /*
 10048       * Check for an Empty Element.
 10049       */
 10050      if ((RAW == '/') && (NXT(1) == '>')) {
 10051          SKIP(2);
 10052          if (ctxt->sax2) {
 10053              if ((ctxt->sax != NULL) && (ctxt->sax->endElementNs != NULL) &&
 10054                  (!ctxt->disableSAX))
 10055                  ctxt->sax->endElementNs(ctxt->userData, name, prefix, URI);
 10056  #ifdef LIBXML_SAX1_ENABLED
 10057          } else {
 10058              if ((ctxt->sax != NULL) && (ctxt->sax->endElement != NULL) &&
 10059                  (!ctxt->disableSAX))
 10060                  ctxt->sax->endElement(ctxt->userData, name);
 10061  #endif /* LIBXML_SAX1_ENABLED */
 10062          }
 10063          namePop(ctxt);
 10064          spacePop(ctxt);
 10065          if (nsNr != ctxt->nsNr)
 10066              nsPop(ctxt, ctxt->nsNr - nsNr);
 10067          if ( ret != NULL && ctxt->record_info ) {
 10068             node_info.end_pos = ctxt->input->consumed +
 10069                                (CUR_PTR - ctxt->input->base);
 10070             node_info.end_line = ctxt->input->line;
 10071             node_info.node = ret;
 10072             xmlParserAddNodeInfo(ctxt, &node_info);
 10073          }
 10074          return(1);
 10075      }
 10076      if (RAW == '>') {
 10077          NEXT1;
 10078      } else {
 10079          xmlFatalErrMsgStrIntStr(ctxt, XML_ERR_GT_REQUIRED,
 10080                       "Couldn't find end of Start Tag %s line %d\n",
 10081                                  name, line, NULL);
 10082
 10083          /*
 10084           * end of parsing of this node.
 10085           */
 10086          nodePop(ctxt);
 10087          namePop(ctxt);
 10088          spacePop(ctxt);
 10089          if (nsNr != ctxt->nsNr)
 10090              nsPop(ctxt, ctxt->nsNr - nsNr);
 10091
 10092          /*
 10093           * Capture end position and add node
 10094           */
 10095          if ( ret != NULL && ctxt->record_info ) {
 10096             node_info.end_pos = ctxt->input->consumed +
 10097                                (CUR_PTR - ctxt->input->base);
 10098             node_info.end_line = ctxt->input->line;
 10099             node_info.node = ret;
 10100             xmlParserAddNodeInfo(ctxt, &node_info);
 10101          }
 10102          return(-1);
 10103      }
 10104
 10105      return(0);
 10106  }
