 10146  /**
 10147   * xmlParseVersionNum:
 10148   * @ctxt:  an XML parser context
 10149   *
 10150   * parse the XML version value.
 10151   *
 10152   * [26] VersionNum ::= '1.' [0-9]+
 10153   *
 10154   * In practice allow [0-9].[0-9]+ at that level
 10155   *
 10156   * Returns the string giving the XML version number, or NULL
 10157   */
 10158  xmlChar *
 10159  xmlParseVersionNum(xmlParserCtxtPtr ctxt) {
 10160      xmlChar *buf = NULL;
 10161      int len = 0;
 10162      int size = 10;
 10163      xmlChar cur;
 10164
 10165      buf = (xmlChar *) xmlMallocAtomic(size * sizeof(xmlChar));
 10166      if (buf == NULL) {
 10167          xmlErrMemory(ctxt, NULL);
 10168          return(NULL);
 10169      }
 10170      cur = CUR;
 10171      if (!((cur >= '0') && (cur <= '9'))) {
 10172          xmlFree(buf);
 10173          return(NULL);
 10174      }
 10175      buf[len++] = cur;
 10176      NEXT;
 10177      cur=CUR;
 10178      if (cur != '.') {
 10179          xmlFree(buf);
 10180          return(NULL);
